import re

def iso_duration_seconds(s):
    # Week form: P<num>W
    m_week = re.fullmatch(r'^P(\d+(?:\.\d+)? )W$', s)
    if m_week:
        weeks = float(m_week.group(1))
        return weeks * 7 * 86400
    # Day-time form
    m = re.fullmatch(
        r'^P(?:(\d+(?:\.\d+)? )D)?'      # optional day part
        r'(?:T(\d+(?:\.\d+)? )H)?'       # optional hour part with T
        r'(?:(\d+(?:\.\d+)? )M)?'       # optional minute part
        r'(?:(\d+(?:\.\d+)? )S)?$',     # optional second part
        s
    )
    if not m:
        raise ValueError
    # ordering constraints
    hour = m.group(2)
    minute = m.group(3)
    second = m.group(4)
    if (minute is not None and hour is None) or (second is not None and minute is None):
        raise ValueError
    if hour is None and minute is None and second is None:
        raise ValueError
    def parse_num(txt):
        return float(txt) if txt else 0.0
    total = 0.0
    day = m.group(1)
    if day:
        total += parse_num(day) * 86400
    if hour:
        total += parse_num(hour) * 3600
    if minute:
        total += parse_num(minute) * 60
    if second:
        total += parse_num(second)
    return total

def run_tests():
    cases = [
        ("PT0S", 0.0),
        ("PT1H30M", 5400.0),
        ("P1DT2H", 93600.0),
        ("P1W", 604800.0),
        ("PT0.5S", 0.5),
        ("P2DT3H4M5.25S", 183845.25),
    ]
    for s, exp in cases:
        assert abs(iso_duration_seconds(s) - exp) < 1e-9, f"{s} -> {iso_duration_seconds(s)} (expected {exp})"
    for bad in ["", "P", "PT", "1H", "P1H"]:
        try:
            iso_duration_seconds(bad)
            assert False, f"Should have raised for {bad}"
        except ValueError:
            pass
    assert abs(iso_duration_seconds("P2W") - 2*604800) < 1e-9
    assert abs(iso_duration_seconds("P0.5W") - 0.5*604800) < 1e-9
    assert abs(iso_duration_seconds("P1DT1H") - (86400 + 3600)) < 1e-9
    for bad in ["P1DT", "P1D", "P1M", "p1w", "P1w", "PT1Y", "P1M", "p1h30m", "P1DT2h", "PT1h30m"]:
        try:
            iso_duration_seconds(bad)
            assert False, f"Should have raised for {bad}"
        except ValueError:
            pass
    print("ALL TESTS PASSED")

run_tests()

